      "content": "{\n  \"name\": \"dsh-cost-pill\",\n  \"description\": \"DeepSeek account balance and per-session cost pill for DeepSeek Harness (dsh): official peak/off-peak token pricing, web search/fetch per-request fees, subagent sessions included, per-model breakdown, no credentials stored.\",\n  \"version\": \"1.3.1\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/types/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/types/client/index.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"cordis.patch.yml\"\n  ],\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"deepseek\",\n    \"deepseek-harness\",\n    \"cost\",\n    \"balance\",\n    \"token-usage\",\n    \"web-search\",\n    \"web-fetch\",\n    \"billing\"\n  ],\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/Arun1016/dsh-cost.git\"\n  },\n  \"homepage\": \"https://github.com/Arun1016/dsh-cost#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/Arun1016/dsh-cost/issues\"\n  },\n  \"license\": \"MIT\",\n  \"engines\": {\n    \"dsh\": \">=0.2.1-rc.2\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-credentials\": \">=0.2.1-rc.2 <0.3.0\",\n    \"@deepseek-ai/schemastery\": \"^3.18.1\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-api-session-controller\",\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-conversation\",\n        \"@deepseek-ai/dsh-client-ui-primitives\",\n        \"@deepseek-ai/dsh-client-ui-renderer\",\n        \"@deepseek-ai/dsh-client-ui-session\"\n      ],\n      \"platform\": \"web\"\n    }\n  }\n}\n"
